begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(40);

insert into auth.users(id,email) select ('a1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'action-'||n||'@example.test' from generate_series(1,9)n;
insert into profiles(id,email,full_name) select id,email,'Action User '||right(id::text,2) from auth.users where id::text like 'a1000000-%';
insert into organizations(id,name,created_by) values('a2000000-0000-4000-8000-000000000001','Action Org','a1000000-0000-4000-8000-000000000001'),('a2000000-0000-4000-8000-000000000002','Other Action Org','a1000000-0000-4000-8000-000000000009');
insert into organization_members(organization_id,user_id,role,status) values
('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Administrator','Active'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000002','Member','Active'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000003','Member','Active'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000004','Member','Active'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000005','Member','Active'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000006','Member','Active'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000007','Member','Inactive'),('a2000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000008','Member','Active'),('a2000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000009','Administrator','Active');
insert into projects(id,organization_id,name,business_objective,project_manager_id,sponsor_name,lifecycle_phase,status,start_date,target_completion_date,overall_health,scope_health,schedule_health,budget_health,resource_health,risk_health,created_by) values
('a3000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','Action Project','Test','a1000000-0000-4000-8000-000000000002','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','a1000000-0000-4000-8000-000000000001'),
('a3000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000001','Sibling','Test','a1000000-0000-4000-8000-000000000008','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','a1000000-0000-4000-8000-000000000001'),
('a3000000-0000-4000-8000-000000000003','a2000000-0000-4000-8000-000000000002','Other','Test','a1000000-0000-4000-8000-000000000009','Sponsor','Initiation','Draft','2026-01-01','2026-12-31','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','Not Assessed','a1000000-0000-4000-8000-000000000009');
insert into project_members(id,project_id,user_id,access_level,left_at) values
('a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000002','Project Manager',null),('a4000000-0000-4000-8000-000000000002','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000003','Project Member',null),('a4000000-0000-4000-8000-000000000003','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000004','Stakeholder',null),('a4000000-0000-4000-8000-000000000004','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000005','Read Only',null),('a4000000-0000-4000-8000-000000000005','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000006','Project Member',now()),('a4000000-0000-4000-8000-000000000006','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000007','Project Member',null),('a4000000-0000-4000-8000-000000000007','a3000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000008','Project Manager',null),('a4000000-0000-4000-8000-000000000008','a3000000-0000-4000-8000-000000000003','a1000000-0000-4000-8000-000000000009','Project Manager',null),('a4000000-0000-4000-8000-000000000009','a3000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000008','Project Manager',null);

select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Admin action','Context','a4000000-0000-4000-8000-000000000001','2026-08-01','Critical')$$,'Administrator creates');
select is((select count(*) from project_actions),1::bigint,'Administrator reads');
select throws_ok($$insert into project_actions(project_id,title,owner_membership_id,due_date,priority,created_by) values('a3000000-0000-4000-8000-000000000001','Direct','a4000000-0000-4000-8000-000000000002','2026-08-01','Low','a1000000-0000-4000-8000-000000000001')$$,'42501','permission denied for table project_actions','Direct insert denied');
select throws_ok($$update project_actions set title='Direct'$$,'42501','permission denied for table project_actions','Direct update denied');select throws_ok($$delete from project_actions$$,'42501','permission denied for table project_actions','Delete denied');reset role;

select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000002',true);set local role authenticated;
select lives_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Member owned','Context','a4000000-0000-4000-8000-000000000002','2026-08-02','High')$$,'Assigned manager creates');
select lives_ok($$select update_project_action((select id from project_actions where title='Member owned'),'Updated','Context','a4000000-0000-4000-8000-000000000002','2026-08-03','Medium')$$,'Assigned manager edits');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000003','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Stakeholder cannot own');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000004','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Read Only cannot own');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000005','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Inactive project owner rejected');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000006','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Inactive organization owner rejected');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000007','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Cross-project owner rejected');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000008','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Cross-org owner rejected');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Bad','', 'a4000000-0000-4000-8000-000000000009','2026-08-01','Low')$$,'23514','The selected action owner is not eligible.','Arbitrary Project Manager label rejected');reset role;

select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000003',true);set local role authenticated;
select is((select count(*) from get_project_actions('a3000000-0000-4000-8000-000000000001')),2::bigint,'Project Member reads all');
select throws_ok($$select create_project_action('a3000000-0000-4000-8000-000000000001','Denied','', 'a4000000-0000-4000-8000-000000000002','2026-08-01','Low')$$,'42501','Action creation is not permitted.','Project Member cannot create');
select lives_ok($$select transition_project_action((select id from project_actions where title='Updated'),'In Progress')$$,'Owner starts own action');
select lives_ok($$select transition_project_action((select id from project_actions where title='Updated'),'Blocked')$$,'Owner blocks own action');
select throws_ok($$select transition_project_action((select id from project_actions where title='Updated'),'Completed',' ')$$,'22023','Completion notes are required.','Completion notes required');
select lives_ok($$select transition_project_action((select id from project_actions where title='Updated'),'Completed','Verified outcome.')$$,'Owner completes own action');
select ok((select completed_by='a1000000-0000-4000-8000-000000000003' and completed_at is not null and completion_notes='Verified outcome.' from project_actions where title='Updated'),'Completion audit trusted');
select throws_ok($$select transition_project_action((select id from project_actions where title='Admin action'),'In Progress')$$,'42501','Action transition is not permitted.','Member cannot change another owner action');
select throws_ok($$select transition_project_action((select id from project_actions where title='Updated'),'Open')$$,'42501','Action transition is not permitted.','Completed action cannot reopen');reset role;

select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000004',true);set local role authenticated;select is((select count(*) from project_actions),2::bigint,'Stakeholder reads');select throws_ok($$select transition_project_action((select id from project_actions limit 1),'Blocked')$$,'42501','Action transition is not permitted.','Stakeholder cannot transition');reset role;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000005',true);set local role authenticated;select is((select count(*) from project_actions),2::bigint,'Read Only reads');select throws_ok($$select transition_project_action((select id from project_actions limit 1),'Blocked')$$,'42501','Action transition is not permitted.','Read Only cannot transition');reset role;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000006',true);set local role authenticated;select is((select count(*) from project_actions),0::bigint,'Inactive project member cannot read');select is_empty($$select * from get_project_actions('a3000000-0000-4000-8000-000000000001')$$,'Inactive member query returns no records');reset role;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000007',true);set local role authenticated;select is((select count(*) from project_actions),0::bigint,'Inactive organization member cannot read');reset role;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000008',true);set local role authenticated;select is((select count(*) from project_actions),2::bigint,'Explicit project membership may read despite manager-like label');select throws_ok($$select transition_project_action((select id from project_actions limit 1),'Blocked')$$,'42501','Action transition is not permitted.','Non-assigned manager cannot mutate');reset role;
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000009',true);set local role authenticated;select is((select count(*) from project_actions),0::bigint,'Cross-org admin cannot read');reset role;

select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);set local role authenticated;
select lives_ok($$select transition_project_action((select id from project_actions where title='Admin action'),'Cancelled')$$,'Manager cancels active action');
select ok((select cancelled_by='a1000000-0000-4000-8000-000000000001' and cancelled_at is not null from project_actions where title='Admin action'),'Cancellation audit trusted');
select throws_ok($$select transition_project_action((select id from project_actions where title='Admin action'),'Open')$$,'42501','Action transition is not permitted.','Cancelled action cannot reopen');
select throws_ok($$select update_project_action((select id from project_actions where title='Admin action'),'Changed','', 'a4000000-0000-4000-8000-000000000001','2026-08-01','Low')$$,'42501','Terminal actions cannot be changed.','Terminal action cannot be edited');
select is((select status from get_project_actions('a3000000-0000-4000-8000-000000000001') limit 1),'Cancelled','Query ordering is deterministic with priority rules');reset role;

set local role anon;select throws_ok($$select * from project_actions$$,'42501','permission denied for table project_actions','Anonymous table read denied');select throws_ok($$select get_project_actions('a3000000-0000-4000-8000-000000000001')$$,'42501','permission denied for function get_project_actions','Anonymous function denied');reset role;
select * from finish();rollback;
